    ("Q-009", "single_lookup", "easy", "What is the letter template for asking a supplier to renew a UN 38.3 certificate?", "Letter template NBC-L-07 (SOP-PUR-005).", ["F-SOP5-1"], ["NBC-L-07"], {}),
    ("Q-010", "single_lookup", "easy", "When does the nightly backup run?", "JOB-SYS-001 runs daily at 01:30; Ledgerline is read-only from 01:30 to 01:50.", ["F-JOB-SYS001", "F-ADM-9.1"], ["01:30"], {}),
