    ("Q-018", "single_lookup", "easy", "By what time must a sales order be confirmed to ship the same day?", "By 15:30 (SOP-SAL-001); it is then delivered next working day in the UK.", ["F-SAL1-CUTOFF"], ["15:30"], {}),
