    # --------------------------------------------------------------------- procedure
    ("Q-101", "procedure", "medium", "How do I onboard a new supplier?", "Follow SOP-PUR-001: search PUR-SUP-03 by a short word of the name, by city and by VAT number and attach the result; raise form NBC-F-112 with a quotation; collect the POL-SUP-003 §3.2 documents; for lithium-cell parts get the UN 38.3 test report and test summary; the purchase manager signs box 7 of NBC-F-112; create the supplier on PUR-SUP-01 (sup_create); upload the certificate (sup_cert_upload); the senior buyer initials checklist NBC-F-113; AP verifies bank details by call-back; the rate contract is set up.",
     ["F-SOP1-SEARCH", "F-SOP1-F112", "F-SOP1-APPR", "F-SOP1-CREATE", "F-SOP1-UPLOAD", "F-SOP1-CHECK", "F-SOP1-BANK"], ["NBC-F-112", "PUR-SUP-01", "NBC-F-113"], {}),
    ("Q-102", "procedure", "easy", "How do I upload a supplier certificate?", "Open the supplier, Certificates tab, press Add, enter certificate type (e.g. UN38.3), document reference and valid-to date, attach the scan and press F8; the status bar shows CERT SAVED.", ["F-MAN-6.5", "F-SOP1-UPLOAD"], ["UN38.3", "CERT SAVED"], {}),
    ("Q-103", "procedure", "medium", "How do I rescue an order stuck in Draft because its cost centre was closed?", "Amend the order on PUR-POM-06 to an open cost centre; it then becomes AP or PA by the normal rules and can be released once approved (warning W-CC-114).", ["F-SOP3-2", "F-MAN-17.6"], ["W-CC-114", "open cost centre"], {}),
    ("Q-104", "procedure", "easy", "What do I do if the screen hangs after I press Save on an order?", "Do not press Save again. Wait one minute, then search the order list by supplier, item and today's date or by client reference; if the order exists, continue from it.", ["F-MAN-19.4"], ["Do not press Save again"], {}),
    ("Q-105", "procedure", "medium", "How do I cancel a purchase order and tell the supplier?", "Press Cancel on PUR-POM-06 and enter a reason; the status becomes CN. Ledgerline sends no cancellation notice, so e-mail the supplier yourself the same day and keep the e-mail on file.", ["F-SOP3-4", "F-MAN-14.5"], ["cancellation notice"], {}),
    ("Q-106", "procedure", "easy", "How do I receive goods against an order?", "On INV-GRN-03 type the PO number and press Fetch, count the goods, enter the quantity and the supplier's delivery note number in Remarks, and Save. A part delivery gets its own GRN.", ["F-SOP-GRN-1"], ["INV-GRN-03", "Remarks"], {}),
    ("Q-107", "procedure", "medium", "What happens when a UN 38.3 certificate is about to expire?", "The senior buyer runs the certificate-expiry report (JOB-PUR-022, 90-day window) on the first working day of each month, writes to the supplier with letter NBC-L-07, sends a second reminder at 60 days; under AMD-SUP-2026-02 no new order once fewer than 60 days remain; on expiry e-mails all buyers 'CERT EXPIRED - DO NOT ORDER'.", ["F-SOP5-1", "F-SOP5-2", "F-SOP5-3", "F-AMD2-3.2"], ["NBC-L-07", "CERT EXPIRED - DO NOT ORDER"], {}),
    ("Q-108", "procedure", "medium", "What do I do with a dropped battery pack?", "Quarantine it even if it looks undamaged: move it to the red quarantine bin in fire cell BAT-Z4, raise an NCR on QA-NCR-02 in the same shift and book it to quality hold on INV-QCH-11.", ["F-SOP-BAT-2", "F-BAT-3.1", "F-QUA2-QCH"], ["BAT-Z4", "QA-NCR-02"], {}),
    ("Q-109", "procedure", "medium", "A supplier e-mails new bank details. What do I do?", "Never accept it by e-mail alone. AP calls the supplier back on a number from its letterhead, website or the supplier master, with two people from AP on the call, and records it on AP-BNK-06 (bnk_verify); until then W-BNK-120 holds payments.", ["F-AP4-CALL", "F-AP4-HOLD"], ["Two people", "W-BNK-120"], {}),
    ("Q-110", "procedure", "easy", "How do I raise a purchase request?", "On PUR-PR-01 enter the item and press F3 (Fetch), check the cost centre is open, enter quantity and need-by date, F8 to save (DR) and F9 to submit.", ["F-SOP2-FETCH", "F-SOP2-CC"], ["PUR-PR-01", "F3"], {}),
    ("Q-111", "procedure", "medium", "How do I return faulty goods to a supplier?", "Raise an RTV on INV-RTV-07 against the GRN within 30 days of receipt, move the goods to WH-MAN-RTV labelled with the RTV number; if the receipt is already invoiced, ask AP for a debit note (AP-DBN-04) instead.", ["F-RET-2.1", "F-SOP-RTV-1", "F-RET-2.2"], ["INV-RTV-07", "30 days", "WH-MAN-RTV"], {}),
    ("Q-112", "procedure", "medium", "How do I raise an order after the request is approved?", "On PUR-PO-01 choose type STD with the PR number, enter supplier and item, press F3 Fetch, check the tax code (VAT20-RC for overseas), F8 Save and read the Status field, then release on PUR-POR-05 with F9.", ["F-SOP2-STD", "F-SOP2-TAX", "F-SOP2-STATUS", "F-SOP2-RL"], ["PUR-PO-01", "PUR-POR-05"], {}),
    ("Q-113", "procedure", "medium", "How does the payment run work?", "Runs on Tuesdays and Thursdays: the proposal job JOB-AP-030 at 10:00, the AP clerk reviews and the AP manager approves (not the proposer), the STD18 file is released by 14:30.", ["F-AP3-DAYS", "F-AP3-FILE"], ["Tuesdays and Thursdays", "14:30"], {}),
    ("Q-114", "procedure", "medium", "How is a damaged-pack incident reported?", "Move the pack to the red quarantine bin in BAT-Z4 and report it to Quality in the same shift with a non-conformance report on QA-NCR-02.", ["F-BAT-3.1"], ["QA-NCR-02"], {}),
    ("Q-115", "procedure", "medium", "How do I submit a travel expense claim?", "Enter it on AP-EXP-09 within 60 days of the expense with a receipt for every item above £10; your line manager approves (T&E Policy v2.4).", ["F-TEX-5.1"], ["AP-EXP-09", "60 days"], {}),
    ("Q-116", "procedure", "medium", "What must I check before booking a parcel with a battery pack?", "Print the lithium battery label (PKG-LBL-UN) before posting the despatch, or Post is refused with ERR-DLV-0320; book the carrier's DGX service.", ["F-SAL-DG", "F-CAR-DGX"], ["ERR-DLV-0320"], {}),
    ("Q-117", "procedure", "hard", "How do I change an approved order's supplier?", "You cannot on PUR-POM-06: it changes only quantity, need-by date or cost centre. Cancel the order and raise a new one.", ["F-SOP3-1"], ["cancel"], {}),
    ("Q-118", "procedure", "medium", "How are battery packs issued to production?", "Not by backflush: battery packs are issued by serial on INV-MRN-08 (SOP-PRD-001).", ["F-PRD1-BAT"], ["INV-MRN-08"], {}),
    ("Q-119", "procedure", "easy", "How do I put battery cartons away?", "Only in fire cells BAT-Z1 to BAT-Z4, checking the count board (max 1,500 packs per cell), on a pallet and never more than four cartons high.", ["F-SOP-BAT-1", "F-BAT-2.2"], ["four"], {}),
    ("Q-120", "procedure", "medium", "What should an approver write when approving an order for a lithium-cell part?", "CERT OK and the certificate's document reference in the approval comment, for example CERT OK UN38.3-TR/VC/2026/118 (Daniel Okafor's e-mail of 2 September 2026).", ["F-EM-CERTOK"], ["CERT OK"], {}),
    # --------------------------------------------------------------------- rule
    ("Q-201", "rule", "easy", "Do chargers need a supplier with a UN 38.3 certificate?", "Yes. Purchase Policy v4.1 §6.2 covers battery packs, hub motors, chargers and any item marked lithium-cell; CHG-4A-01 has the lithium-cell flag.", ["F-PUR-6.2-scope", "F-ITM-CHG"], ["chargers"], {}),
    ("Q-202", "rule", "easy", "What is the direct-order limit without a purchase request?", "£50,000 gross including VAT until 30 November 2026; £25,000 from 1 December 2026 (Amendment 3).", ["F-PUR-3.3", "F-AMD3-1.1", "F-AMD3-1.2"], ["£50,000", "£25,000"], {}),
    ("Q-203", "rule", "easy", "Are approval limits on the basic value or the gross value?", "The gross value including VAT (freight and packing count).", ["F-PUR-5.1", "F-APR-2.1"], ["gross"], {}),
    ("Q-204", "rule", "easy", "Can I approve an order I raised?", "No. Nobody may approve a document they raised; Ledgerline refuses with ERR-APR-0003.", ["F-PUR-5.3"], ["Nobody may approve"], {}),
    ("Q-205", "rule", "medium", "Can I split an order to stay within my limit?", "No. Orders for the same item from the same supplier within seven days are treated as one requirement (approval matrix §2.3).", ["F-APR-2.3"], ["seven days"], {}),
    ("Q-206", "rule", "medium", "When must I tell the requester an order has been placed?", "Only when the order is in status Released (RL) in Ledgerline (Purchase Policy §9.2).", ["F-PUR-9.2", "F-MAN-16.2"], ["Released"], {}),
    ("Q-207", "rule", "medium", "My order is 3% above the contract rate. Is that allowed?", "Only with the manager's written reason in the remarks: Purchase Policy v4.1 §7.2 requires it above 2%.", ["F-PUR-7.2"], ["2%"], {}),
    ("Q-208", "rule", "medium", "Does an expired certificate still count?", "No. An expired certificate counts as no certificate; the supplier stays ACTIVE but no lithium-cell part may be ordered from it.", ["F-PUR-6.2b", "F-SUP-4.5"], ["no certificate"], {}),
    ("Q-209", "rule", "medium", "How do I know if two supplier records are the same supplier?", "The VAT number is the test: two records with the same VAT number are the same supplier (Supplier Policy §6.1).", ["F-SUP-6.1"], ["VAT number"], {}),
    ("Q-210", "rule", "easy", "Which tax code does an overseas supplier get?", "A reverse-charge code ending -RC, normally VAT20-RC (Purchase Policy §8.1).", ["F-PUR-8.1", "F-TAX-RC"], ["-RC"], {}),
    ("Q-211", "rule", "medium", "Does approval of the request cover the order?", "Yes, provided the request approver's limit covers the order's gross value (Purchase Policy §5.4).", ["F-PUR-5.4"], ["covers"], {}),
    ("Q-212", "rule", "medium", "Can a service account approve purchase orders?", "No. Service accounts (role SYS-ADMIN, e.g. SVC_AGENT) have no approval authority; a document they approve is treated as unapproved.", ["F-APR-4.2"], ["SVC_AGENT"], {}),
    ("Q-213", "rule", "medium", "Who approves an order above £5,000,000?", "The Managing Director, in writing outside Ledgerline; Ledgerline shows ERR-APR-0009 and the plant head's office records the approval.", ["F-APR-3.4"], ["Managing Director"], {}),
    ("Q-214", "rule", "medium", "Can I delegate my approvals to a purchase executive while I am on leave?", "Only to someone of the same or a higher role, in writing; delegation to a lower role is not allowed (ERR-DLG-0210 in Ledgerline).", ["F-APR-4.3", "F-ADM-3.1"], ["lower role"], {}),
    ("Q-215", "rule", "easy", "What is the gift limit before I must declare it?", "Gifts worth more than £50 are declared in the gifts register within five working days; no gifts at all from a supplier in an open quotation.", ["F-ABC-2.1", "F-ABC-2.2"], ["£50"], {}),
    ("Q-216", "rule", "medium", "How many quotations does a new requirement need?", "Three written quotations for a new requirement above £100,000 gross, compared on NBC-F-118 (SOP-PUR-006).", ["F-SOP6-1"], ["three", "NBC-F-118"], {}),
    ("Q-217", "rule", "medium", "At what state of charge are battery packs stored?", "Between 30% and 50%; never charged in the store (POL-BAT-004 §2.3).", ["F-BAT-2.3"], ["30%", "50%"], {}),
    ("Q-218", "rule", "medium", "How many packs can one fire cell hold?", "No more than 1,500 packs per fire cell; the Manchester fire-cell area holds at most 6,000.", ["F-BAT-2.2"], ["1,500", "6,000"], {}),
    ("Q-219", "rule", "easy", "What is the warranty on a frame and on a battery pack?", "Frames carry a 5-year warranty; battery packs, motors, chargers and other parts a 2-year warranty from sale to the rider.", ["F-RET-3.1"], ["5-year", "2-year"], {}),
    ("Q-220", "rule", "medium", "Can a warranty battery pack go back into stock?", "No. It goes to battery refurbishment (cost centre PRD-09) or for recycling.", ["F-RET-3.2"], ["PRD-09"], {}),
    ("Q-221", "rule", "medium", "What AQL is used for incoming lithium-cell parts?", "AQL 0.65 (other parts AQL 1.5), plus an open-circuit voltage check on every sample pack.", ["F-QUA-3.1"], ["0.65"], {}),
    ("Q-222", "rule", "easy", "How long are supplier certificates kept?", "10 years after the supplier is blocked.", ["F-DRP-CERT"], ["10 years"], {}),
    ("Q-223", "rule", "medium", "Can a new supplier be ordered from as soon as it is created?", "It is ACTIVE at once, but no order may be placed until every onboarding document and, for lithium-cell parts, the certificate is on file (Supplier Policy §3.5); Ledgerline will not hold it back.", ["F-SUP-3.5", "F-MAN-6.4"], ["ACTIVE"], {}),
    ("Q-224", "rule", "medium", "What is the meal allowance on an overnight trip?", "£35 a day with receipts (T&E v2.4, in force); it becomes £40 from 1 January 2027 (v3.0).", ["F-TEX-3.2", "F-TEX3-3.2"], ["£35"], {}),
    # --------------------------------------------------------------------- service / field reference
    ("Q-301", "service_field", "medium", "Which fields are mandatory when calling po_save?", "sup_cd, itm_cd, qty, rate, tax_cd, cc_cd and need_dt are required; po_type, pr_no, whs_cd, fetch_tok and client_ref are optional (but Save needs a valid fetch_tok from po_fetch).", ["F-SVC-po_save"], ["sup_cd", "tax_cd", "need_dt"], {}),
    ("Q-302", "service_field", "medium", "What does po_fetch return as the tax code?", "Always VAT20-UK, whatever the supplier's country; an overseas supplier needs VAT20-RC on po_save.", ["F-SVCNOTE-po_fetch", "F-MAN-11.4"], ["VAT20-UK"], {}),
    ("Q-303", "service_field", "medium", "Which fields does sup_create take?", "name, city and state (country code, two letters) are required; vat_no and pt_cd are optional.", ["F-SVC-sup_create"], ["name", "city", "state"], {}),
    ("Q-304", "service_field", "medium", "What fields does sup_cert_upload need?", "sup_cd, cert_type, doc_ref and valid_to, all required.", ["F-SVC-sup_cert_upload"], ["cert_type", "doc_ref", "valid_to"], {}),
    ("Q-305", "service_field", "medium", "Which errors can po_save return?", "Among others ERR-SCR-0221, ERR-SUP-0030, ERR-SUP-0031, ERR-PO-0412, ERR-PO-0602, ERR-PO-0603, ERR-PO-0610, ERR-BUD-0207, and the warning W-CC-114.", ["F-SVCERR-po_save-ERR-PO-0412", "F-SVCERR-po_save-ERR-SCR-0221", "F-SVCERR-po_save-ERR-PO-0610"], ["ERR-PO-0412", "ERR-SCR-0221"], {}),
    ("Q-306", "service_field", "easy", "Which screen does po_release belong to?", "PUR-POR-05 (purchase order release).", ["F-SVC-po_release"], ["PUR-POR-05"], {}),
    ("Q-307", "service_field", "medium", "What does pr_save compute as the estimated value?", "est_value = qty x est_rate x 1.20 (Ledgerline assumes 20% VAT on every request).", ["F-SVCNOTE-pr_save", "F-MAN-9.4"], ["1.20"], {}),
    ("Q-308", "service_field", "medium", "What is fetch_tok?", "A token returned by po_fetch and required by po_save; it is valid once, for one supplier and item.", ["F-DD-6.8", "F-SVCNOTE-po_fetch"], ["valid once"], {}),
    ("Q-309", "service_field", "medium", "Which fields does grn_save take?", "po_no and qty are required; whs_cd and remarks are optional.", ["F-SVC-grn_save"], ["po_no", "qty"], {}),
    ("Q-310", "service_field", "medium", "What does the state field of a supplier mean?", "The two-letter country code of the supplier (GB, NL, PL); the column keeps its 1998 name.", ["F-DD-2.2", "F-DD-XL-STATE"], ["1998"], {}),
    ("Q-311", "service_field", "easy", "Which screen does sup_create use?", "PUR-SUP-01 (supplier master create).", ["F-SVC-sup_create"], ["PUR-SUP-01"], {}),
    ("Q-312", "service_field", "medium", "Which error does sup_create raise for a duplicate?", "ERR-SUP-0118 VAT NO ALREADY REGISTERED; duplicates are caught only by VAT number.", ["F-SVCERR-sup_create-ERR-SUP-0118", "F-SVCNOTE-sup_create"], ["ERR-SUP-0118"], {}),
    ("Q-313", "service_field", "medium", "What does po_release require the order status to be?", "AP (approved); otherwise ERR-PO-0715.", ["F-SVCERR-po_release-ERR-PO-0715", "F-SVCNOTE-po_release"], ["ERR-PO-0715"], {}),
    ("Q-314", "service_field", "medium", "Which fields does po_amend accept?", "po_no (required), and optionally qty, need_dt and cc_cd.", ["F-SVC-po_amend"], ["po_no", "cc_cd"], {}),
    ("Q-315", "service_field", "medium", "How is cover_days computed by stk_query?", "(on_hand - allocated) / avg_daily_issue, rounded down.", ["F-SVCNOTE-stk_query", "F-MAN-4.3"], ["avg_daily_issue"], {}),
    ("Q-316", "service_field", "easy", "How many purchasing services are there?", "38, in 04_service_definitions/purchase.", ["F-SVC-38"], ["38"], {}),
    ("Q-317", "service_field", "medium", "What fields does pr_submit take?", "pr_no only (required).", ["F-SVC-pr_submit"], ["pr_no"], {}),
    ("Q-318", "service_field", "medium", "What does pr_fetch return as the estimated rate?", "The rate on the last released order for the item, not the contract rate.", ["F-SVCNOTE-pr_fetch", "F-SOP2-FETCH"], ["last released order"], {}),
    ("Q-319", "service_field", "medium", "Which errors can grn_save return?", "ERR-PO-0001, ERR-GRN-0102 (PO not released), ERR-GRN-0105 (already fully received), ERR-GRN-0201 and ERR-GRN-0204 (qty exceeds PO balance).", ["F-SVCERR-grn_save-ERR-GRN-0102", "F-SVCERR-grn_save-ERR-GRN-0204"], ["ERR-GRN-0102", "ERR-GRN-0204"], {}),
    ("Q-320", "service_field", "medium", "What does po_approve refuse?", "ERR-PO-0702 if the order is not pending approval, ERR-APR-0003 for self approval and ERR-APR-0004 above the approver's limit.", ["F-SVCERR-po_approve-ERR-APR-0003", "F-SVCERR-po_approve-ERR-APR-0004"], ["ERR-APR-0003"], {}),
    ("Q-321", "service_field", "medium", "Does saving a certificate check its dates?", "No. sup_cert_upload does not check the certificate's dates; cert_type is stored in capitals.", ["F-SVCNOTE-sup_cert_upload"], ["does not check"], {}),
    ("Q-322", "service_field", "medium", "What does the status bar say after po_save?", "'<PO NO> SAVED' whatever the status; read data.status (DR, PA or AP).", ["F-SVCNOTE-po_save", "F-MAN-11.8"], ["SAVED"], {}),
    ("Q-323", "service_field", "hard", "What is the item master's lithium-cell field called?", "cell_safety (1 if the part contains or charges lithium cells, set by Quality).", ["F-DD-XL-CELL"], ["cell_safety"], {}),
    ("Q-324", "service_field", "medium", "What happens to a released order when po_amend increases it beyond its approval?", "It goes back to PA for approval, even though it was released.", ["F-SVCNOTE-po_amend", "F-SOP3-3"], ["PA"], {}),
    # --------------------------------------------------------------------- table lookup (Excel)
    ("Q-401", "table_lookup", "easy", "What is the reorder level of BAT-500?", "3,000 (average daily issue 600).", ["F-ITM-BAT500"], ["3000"], {}),
    ("Q-402", "table_lookup", "easy", "What is Voltway Cells' contract rate for BAT-500 now?", "£119.00, from 1 October 2026 to 31 March 2027 (it was £114.00 from April to September).", ["F-RATE-VC500", "F-RATE-VC500-OLD"], ["119.00"], {}),
    ("Q-403", "table_lookup", "easy", "How many BAT-500 are in Manchester main stores?", "5,400 on hand in WH-MAN-STR at 26 October 2026, 09:00 (plus 1,200 in Leeds). Stock figures change all day.", ["F-STK-BAT500-MAN", "F-STK-BAT500-LDS"], ["5400"], {}),
    ("Q-404", "table_lookup", "easy", "When does Voltway's UN 38.3 certificate expire?", "31 March 2027 (valid_to 2027-03-31; UN38.3-TR/VC/2026/118, issued 27 March 2026).", ["F-CERT-VC"], ["2027-03-31"], {}),
    ("Q-405", "table_lookup", "medium", "Is Nordic Cell's certificate valid?", "No. UN38.3-TR/NC/2025/090 expired on 30 September 2026 (valid_to 2026-09-30).", ["F-CERT-NC", "F-RPT-NC"], ["2026-09-30"], {}),
    ("Q-406", "table_lookup", "easy", "What is Nordic Cell's rate for BAT-500?", "£111.00 (contract to 31 March 2027) - but its certificate has expired, so no orders.", ["F-RATE-NC500"], ["111.00"], {}),
    ("Q-407", "table_lookup", "easy", "Is cost centre PRD-05 open?", "No. PRD-05 (city e-bike line) is CLOSED, closed_on 2026-10-15.", ["F-CC-PRD05"], ["CLOSED", "2026-10-15"], {}),
    ("Q-408", "table_lookup", "medium", "How much budget is left on PRD-07 this quarter?", "2026-Q4: amount £1,500,000, committed £310,000, available £1,190,000.", ["F-BUD-PRD07"], ["1500000", "310000"], {}),
    ("Q-409", "table_lookup", "easy", "What is Emma Clarke's approval limit?", "£250,000 gross (ECLARKE, PUR-EXEC); her manager is DOKAFOR.", ["F-USR-EMMA", "F-APR-EXEC"], ["250000"], {}),
    ("Q-410", "table_lookup", "medium", "Does DSP-02 count as a lithium-cell part?", "Yes: DSP-02 (colour TFT display with coin cell) has the lithium-cell flag 1, so §6.2 applies.", ["F-ITM-DSP02"], ["1"], {}),
    ("Q-411", "table_lookup", "medium", "Is BAT-BMS-36 a lithium-cell part?", "No: the battery management board has lithium-cell flag 0 (no cells).", ["F-ITM-BMS"], ["0"], {}),
    ("Q-412", "table_lookup", "easy", "What is the rate for CHG-4A-01 from Castlefield Chargers?", "£96.00.", ["F-RATE-CHG"], ["96.00"], {}),
    ("Q-413", "table_lookup", "easy", "What is the rate for MTR-HUB-250?", "£142.00 from Albion Motors.", ["F-RATE-MTR"], ["142.00"], {}),
    ("Q-414", "table_lookup", "easy", "What does payment term N45 mean?", "Net 45 days.", ["F-PT-N45"], ["Net 45 days"], {}),
    ("Q-415", "table_lookup", "easy", "Is BAT-400-OLD still active?", "No, it is inactive (active 0).", ["F-ITM-BAT400"], ["0"], {}),
    ("Q-416", "table_lookup", "medium", "What was the BAT-500 rate in 2025-26?", "£109.50 from Voltway (rate contract 2025-26, expired).", ["F-RATE-VC500-2526"], ["109.50"], {}),
    ("Q-417", "table_lookup", "easy", "What is Castlefield Chargers' certificate valid-to date?", "31 January 2027 (2027-01-31).", ["F-CERT-CC"], ["2027-01-31"], {}),
    ("Q-418", "table_lookup", "easy", "What is Albion Motors' certificate valid-to date?", "30 June 2027 (2027-06-30).", ["F-CERT-AM"], ["2027-06-30"], {}),
    ("Q-419", "table_lookup", "medium", "What status is PO/2026/01179?", "PA (pending approval): Castlefield Chargers, CHG-4A-01, 4,000.", ["F-PO-1179"], ["PA"], {}),
    ("Q-420", "table_lookup", "medium", "At what rate was PO/2026/01120 placed?", "£114.00 for 1,800 BAT-500 from Voltway, VAT20-RC, released 14 September 2026.", ["F-PO-1120"], ["114.00"], {}),
    ("Q-421", "table_lookup", "easy", "What is Luis Moreno's approval limit?", "£500,000 (PUR-SR).", ["F-USR-LUIS", "F-APR-SR"], ["500000"], {}),
    ("Q-422", "table_lookup", "medium", "What is the warehouse WH-MAN-BAT?", "An old 6.x code for the battery store, merged into WH-MAN-STR in 2019; do not use.", ["F-WHS-BAT"], ["merged into WH-MAN-STR"], {}),
    ("Q-423", "table_lookup", "medium", "What is the UN number in the item master for BAT-500?", "UN3480.", ["F-ITM-UN"], ["UN3480"], {}),
    ("Q-424", "table_lookup", "medium", "What is the rate for BAT-375 from Voltway?", "£92.00.", ["F-RATE-VC375"], ["92.00"], {}),
    ("Q-425", "table_lookup", "medium", "What is the status of cost centre PRD-08?", "PLANNED: Roch mountain line, opens 2027.", ["F-CC-PRD08"], ["PLANNED"], {}),
    ("Q-426", "table_lookup", "hard", "What does the disciplinary register say about case DC-2026-005?", "Confidential HR record: final written warning, under appeal. (HR only.)", ["F-HR-DC5"], ["Final written warning"], {"asker_role": "HR-MGR"}),
    # --------------------------------------------------------------------- multi-hop
    ("Q-501", "multi_hop", "hard", "Emma wants 2,000 BAT-500 from Voltway. Who has to approve the order?", "At £119.00 the basic value is £238,000, VAT 20% £47,600, gross £285,600. Limits are on the gross value, and Emma's limit is £250,000, so it goes to her manager Daniel Okafor (limit £1,000,000).", ["F-RATE-VC500", "F-APR-5.1", "F-USR-EMMA", "F-APR-MGR"], ["£285,600", "Daniel Okafor"], {}),
    ("Q-502", "multi_hop", "hard", "Can I order BAT-500 from Nordic Cell? They're cheaper.", "No. Nordic Cell's rate is £111.00, but its UN 38.3 certificate expired on 30 September 2026, and an expired certificate counts as no certificate (§6.2). Luis's e-mail of 1 October says no lithium-cell orders until a new report is uploaded; the new report is expected in late November.", ["F-RATE-NC500", "F-CERT-NC", "F-PUR-6.2b", "F-EM-NORDIC", "F-EM-NORDIC-DELAY"], ["£111.00", "30 September 2026"], {}),
    ("Q-503", "multi_hop", "hard", "I saved an order on my default cost centre and it says SAVED. Is it with the supplier?", "Probably not. Emma's default cost centre is PRD-05, closed on 15 October 2026. An order on a closed cost centre is saved as Draft (DR) with W-CC-114 and the message still says SAVED; only RL reaches the supplier. Amend it to PRD-07 (spring launch run) and release it after approval.", ["F-USR-EMMA", "F-CC-PRD05", "F-MAN-17.6", "F-MAN-11.8", "F-EM-PRD07"], ["PRD-05", "W-CC-114", "PRD-07"], {}),
    ("Q-504", "multi_hop", "hard", "Is a UN 38.3 certificate that expires on 15 December 2026 good enough for an order today (26 October 2026)?", "No. Since 1 September 2026 (AMD-SUP-2026-02) the certificate must be valid at least 60 days after the order date and issued within the last 12 months; 15 December is only 50 days away. The old 24-month rule in Supplier Policy §4.4 no longer applies.", ["F-AMD2-1.1", "F-SUP-4.4"], ["60 days"], {}),
    ("Q-505", "multi_hop", "hard", "Does Ledgerline stop me ordering from a supplier without a certificate?", "No. The manuals say Ledgerline does not check certificates on the order screen; patch 7.2.3-P4 added an optional warning (PUR.CERT_CHK, W-SUP-0207) but the order still saves, and the change board decided on 7 October 2026 to keep PUR.CERT_CHK at N until after the spring launch. The check is the raiser's and the approver's job (Supplier Policy §4.7).", ["F-MAN-11.11", "F-RNP4-CERT", "F-CAB-031", "F-SUP-4.7", "F-ADM-CERTCHK"], ["PUR.CERT_CHK", "W-SUP-0207"], {}),
    ("Q-506", "multi_hop", "hard", "How many more battery packs can Manchester main stores take?", "The fire-cell area holds at most 6,000 packs (4 cells x 1,500) and 5,400 BAT-500 are on hand in WH-MAN-STR, so about 600 more, unless issues are made first.", ["F-BAT-2.2", "F-STK-BAT500-MAN", "F-BAT-2.1"], ["6,000", "5400"], {}),
    ("Q-507", "multi_hop", "hard", "We received Voltway battery packs. Which warehouse do they go into?", "Straight into Manchester main stores (WH-MAN-STR), per Daniel Okafor's e-mail of 15 June 2026; Quality samples them at the receiving bay. The goods-receipt SOP still says lithium-cell parts go to WH-MAN-QC, which now applies only to other lithium-cell parts.", ["F-EM-GRN-OVR", "F-SOP-GRN-QC"], ["WH-MAN-STR", "WH-MAN-QC"], {}),
    ("Q-508", "multi_hop", "medium", "I found two Voltway suppliers. Which one do I use for battery packs?", "Voltway Cells, Eindhoven, VC-EIN-0042. Voltway Paints & Coatings, Rotterdam (VPC-ROT-0107) is a different supplier, and VC-EIN-0009 is Voltway Cells' old blocked code.", ["F-SUP-VC42", "F-SUP-VPC", "F-SUP-6.3", "F-SUP-VC09"], ["VC-EIN-0042", "VPC-ROT-0107"], {}),
    ("Q-509", "multi_hop", "hard", "Can I buy hub motors from a supplier whose UN 38.3 report is 18 months old but not expired?", "No. Hub motors are lithium-cell parts (MTR-HUB-250 flag 1, §6.2). Since 1 September 2026 a report must be issued within the last 12 months (AMD-SUP-2026-02); the old 24-month rule was replaced.", ["F-ITM-MTR", "F-PUR-6.2-scope", "F-AMD2-1.1", "F-AMD2-1.2"], ["12 months"], {}),
    ("Q-510", "multi_hop", "hard", "Can I raise a direct order for £40,000 of brake pads next month?", "It depends on the date. Today the direct-order limit is £50,000 gross, so £40,000 is fine; from 1 December 2026 (Amendment 3) the limit is £25,000 and Ledgerline will refuse it with ERR-PO-0610, so raise a request instead. Brake pads are not lithium-cell parts.", ["F-PUR-3.3", "F-AMD3-1.1", "F-AMD3-3.1", "F-ITM-BRK"], ["£25,000", "ERR-PO-0610"], {}),
    ("Q-511", "multi_hop", "hard", "Why did PO/2026/01120 cost £114 but a new order costs £119?", "PO/2026/01120 was placed in September at £114.00, the rate valid from 1 April to 30 September 2026. Voltway's new rate of £119.00 applies from 1 October 2026 (their letter of 24 September). Old order rates are history; use the current contract (§7.1).", ["F-PO-1120", "F-RATE-VC500-OLD", "F-RATE-VC500", "F-EM-VC119", "F-PUR-7.1"], ["£114.00", "£119.00"], {}),
    ("Q-512", "rule", "hard", "Who should approve a £720,000 order raised by the senior buyer, and what if he raised £1,200,000?", "£720,000 gross is above the senior buyer's £500,000, so the purchase manager (limit £1,000,000) approves. £1,200,000 goes to the plant head, Henrik Weber (limit £5,000,000).", ["F-APR-SR", "F-APR-MGR", "F-APR-PH"], ["£500,000", "£1,000,000"], {}),
    ("Q-513", "multi_hop", "medium", "Do I need a certificate for DSP-02 displays from a new supplier?", "Yes. DSP-02 carries the lithium-cell flag (coin cell), and §6.2 covers any item marked lithium-cell in the item master.", ["F-ITM-DSP02", "F-PUR-6.2-scope"], ["lithium-cell"], {}),
    ("Q-514", "multi_hop", "hard", "Our integration wants to use SVC_AGENT to create and approve orders. Is that OK?", "No. SVC_AGENT has role SYS-ADMIN with every service and an approval limit of 1e12, but under the approval matrix §4.2 service accounts have no approval authority, and IT finding ITS-2026-07 says no new integration may use SVC_AGENT until the review closes.", ["F-USR-SVC", "F-APR-4.2", "F-ITS-4.2", "F-SVC-AGENT"], ["ITS-2026-07"], {}),
    ("Q-515", "multi_hop", "hard", "Emma's request for 2,000 BAT-500: what estimated value will Ledgerline show?", "pr_fetch fills the estimated rate from the last released order (£114.00 on PO/2026/01120), and the estimate is qty x rate x 1.20 = 2,000 x £114.00 x 1.20 = £273,600.", ["F-SOP2-FETCH", "F-PO-1120", "F-MAN-9.4", "F-EM-EST"], ["£273,600"], {}),
    ("Q-516", "multi_hop", "medium", "A supplier was entered without a VAT number and may be a duplicate. Will Ledgerline catch it?", "No. Ledgerline refuses a duplicate only by VAT number (ERR-SUP-0118); a supplier entered without a VAT number is never checked. The proposer must search by name, city and VAT number (Supplier Policy §3.3, §6.4).", ["F-SUP-6.4", "F-SVCNOTE-sup_create", "F-SUP-3.3"], ["ERR-SUP-0118"], {}),
    ("Q-517", "multi_hop", "hard", "How long will onboarding Brightcell take?", "At least ten working days for a lithium-cell supplier (SOP-PUR-001 §6.1; five working days is the normal minimum from a complete file), and in practice not before their renewed UN 38.3 report arrives, expected December 2026.", ["F-SOP1-TIME", "F-SUP-3.6", "F-EM-BRIGHT-CERT"], ["ten working days"], {}),
    ("Q-518", "multi_hop", "medium", "Which cost centre should the spring launch packs go on?", "PRD-07 (Spring launch run), open since 1 October 2026; PRD-05 closed on 15 October.", ["F-EM-PRD07", "F-CC-PRD07", "F-CC-PRD05"], ["PRD-07"], {}),
    ("Q-519", "multi_hop", "hard", "If I approve a Castlefield charger order, what must I check and write?", "CHG-4A-01 is a lithium-cell part (§6.2), so the supplier needs a valid UN 38.3 certificate (Castlefield's is valid to 2027-01-31, more than 60 days away); write CERT OK and the document reference in the approval comment (Daniel's e-mail of 2 September 2026).", ["F-ITM-CHG", "F-CERT-CC", "F-EM-CERTOK", "F-AMD2-1.1"], ["CERT OK", "2027-01-31"], {}),
    ("Q-520", "multi_hop", "medium", "What is the full gross price of 2,000 packs at the Brightcell quote vs Voltway?", "Brightcell: 2,000 x £104.00 = £208,000 basic; Voltway: 2,000 x £119.00 = £238,000 basic, £285,600 gross. But Brightcell cannot be ordered from yet (not onboarded, no valid certificate).", ["F-EM-BRIGHT-PRICE", "F-APR-5.1", "F-SUP-NOBRIGHT"], ["£104.00", "£285,600"], {}),
    ("Q-521", "multi_hop", "hard", "An invoice line is £40 above the order on a £5,000 line. Will it be held?", "No: the hold applies when the rate differs by more than 2% or more than £50 per line, whichever is smaller; £40 is 0.8% and under £50 (SOP-AP-001; parameters AP.MATCH_TOL_PCT/ABS).", ["F-AP1-TOL", "F-AP-MATTOL"], ["£50"], {}),
    ("Q-522", "single_lookup", "medium", "Which documents support the CERT OK rule?", "Only Daniel Okafor's e-mail of 2 September 2026; it says the rule is not in any policy yet. QRC-06 repeats it.", ["F-EM-CERTOK"], ["not in any policy"], {}),
    # --------------------------------------------------------------------- version / conflict
    ("Q-601", "version_conflict", "medium", "How long before an idle Ledgerline session is closed?", "15 minutes since patch 7.2.3-P2 (March 2026; parameter SYS.SESSION_TIMEOUT). The vendor manuals (7.2.3, January 2025) still say 20 minutes and were not reissued.", ["F-RNP2-TIMEOUT", "F-ITS-3.1", "F-MAN-2.4", "F-EM-P2"], ["15 minutes", "20"], {}),
    ("Q-602", "version_conflict", "medium", "What is the cycle-count tolerance?", "1.5% by value in Ledgerline since 7.2.2 (June 2024; INV.CNT_TOL_PCT). The stock count SOP (2023) and the old 7.2.2 inventory manual still say 2%.", ["F-RN722-CNT", "F-INV-CNTTOL", "F-SOP-CNT-TOL", "F-ADM-CNTTOL"], ["1.5%", "2%"], {}),
    ("Q-603", "version_conflict", "medium", "What is the AP cut-off at month end?", "Working day 2 at 12:00 since the June 2026 close (Grace Whitaker's e-mail of 2 June 2026). SOP-AP-002 v3.0 still says working day 3.", ["F-EM-CUTOFF", "F-AP2-CUTOFF"], ["working day 2"], {}),
    ("Q-604", "version_conflict", "medium", "How old can a UN 38.3 report be?", "Issued within the last 12 months and valid at least 60 days after the order date (AMD-SUP-2026-02, from 1 September 2026). Supplier Policy v2.3 §4.4 still prints the old rule of 24 months.", ["F-AMD2-1.1", "F-SUP-4.4"], ["12 months", "24 months"], {}),
    ("Q-605", "version_conflict", "medium", "What is a purchase executive's approval limit?", "£250,000 gross under approval matrix v3.0 (April 2026). The superseded v2.0 (2024) and the 2024 induction deck say £200,000; the 2016 intranet said £150,000 on net value.", ["F-APR-EXEC", "F-APR20-EXEC", "F-DECK-LIMIT", "F-INTRA-LIMITS"], ["£250,000", "£200,000"], {}),
    ("Q-606", "version_conflict", "medium", "What is the price tolerance before a manager's reason is needed?", "2% above contract under Purchase Policy v4.1 (April 2026); the superseded v4.0 allowed 5%.", ["F-PUR-7.2", "F-PUR40-7.2"], ["2%", "5%"], {}),
    ("Q-607", "version_conflict", "medium", "Is Fetch optional on the order screen?", "No. Since 7.2.3 (January 2025) Save is refused with ERR-SCR-0221 without Fetch. The 7.0 manual, SOP-PUR-002 v1.3 and the 2016 intranet said Fetch was optional.", ["F-RN723-FETCH", "F-MAN-11.3", "F-PUR70-FETCH", "F-SOP2-OLD"], ["ERR-SCR-0221"], {}),
    ("Q-608", "version_conflict", "medium", "What does ERR-PO-0412 say on screen, and what did it say before?", "Now: TAX CODE DOES NOT MATCH SUPPLIER COUNTRY (country). Before patch 7.2.3-P1 (June 2025) it read TAX REGION DOES NOT MATCH SUPPLIER STATE; the rule is unchanged.", ["F-RNP1-0412", "F-PUR70-0412", "F-INTRA-0412"], ["TAX REGION DOES NOT MATCH SUPPLIER STATE"], {}),
    ("Q-609", "version_conflict", "medium", "What are the Ledgerline password rules?", "At Northbridge: at least 12 characters, expiring every 60 days (IT Security Policy v3.2, overriding the vendor default of 8 characters and 90 days in the manual).", ["F-ITS-2.1", "F-MAN-2.6"], ["12 characters", "60 days"], {}),
    ("Q-610", "version_conflict", "medium", "What hotel rate can I book in London?", "Up to £190 a night under the T&E Policy v2.4, in force today. v3.0 (£210) applies only from 1 January 2027.", ["F-TEX-3.1", "F-TEX3-3.1", "F-TEX3-1.1"], ["£190", "£210"], {}),
    ("Q-611", "version_conflict", "hard", "Will Ledgerline 7.3 block orders without a certificate? Is that in place?", "The 7.3 preview (planned March 2027, not installed) describes a blocking check (ERR-SUP-0207). Today only the optional P4 warning exists, and it is switched off.", ["F-RN73-BLOCK", "F-RN73-DATE", "F-RNP4-CERT", "F-CAB-031"], ["March 2027", "not installed"], {}),
    ("Q-612", "version_conflict", "medium", "Can the UN 38.3 report come after the first order?", "No: it must be uploaded and checked before the first order (§6.2). The superseded SOP-PUR-001 v2.0 (2021) allowed three months after.", ["F-PUR-6.2b", "F-SOP1-OLD"], ["before the first order"], {}),
    ("Q-613", "version_conflict", "medium", "What was BAT-500's reorder level in the March 2025 export, and what is it now?", "2,500 in the old March 2025 export; 3,000 in the current item master.", ["F-ITMOLD-BAT500", "F-ITM-BAT500"], ["2500", "3000"], {}),
    ("Q-614", "version_conflict", "medium", "What did the 2019 policy say about direct orders?", "Purchase Policy v3.0 (2019) allowed direct orders up to £30,000; today it is £50,000 (until 30 November 2026).", ["F-PUR30-3.3", "F-PUR-3.3"], ["£30,000", "£50,000"], {}),
    ("Q-615", "version_conflict", "medium", "Did chargers always need UN 38.3?", "No. Purchase Policy v4.0 (2025) named only battery packs and hub motors; v4.1 (April 2026) added chargers.", ["F-PUR40-6.2", "F-PUR-6.2-scope"], ["chargers"], {}),
    ("Q-616", "version_conflict", "medium", "Where are approval limits stored in Ledgerline?", "On the user since Ledgerline 7.0 (the 7.0 manual described limits on roles).", ["F-RN70-LIM", "F-MAN-24.1", "F-PUR70-LIMITS"], ["users"], {}),
    ("Q-617", "version_conflict", "medium", "What is the tax code for standard-rate VAT on a UK supplier, and what was V1?", "VAT20-UK. V1 was the Ledgerline 6 code for 17.5% standard-rate VAT, inactive since January 2011.", ["F-LL6-V1", "F-SCAN-VAT", "F-TAX-V175"], ["VAT20-UK", "17.5%"], {}),
    ("Q-618", "version_conflict", "hard", "How long do I have to submit an expense claim?", "60 days under T&E v2.4 (in force); 45 days only from 1 January 2027 under v3.0.", ["F-TEX-5.1", "F-TEX3-5.1"], ["60 days", "45 days"], {}),
    ("Q-619", "version_conflict", "medium", "Is the direct-order limit in Ledgerline already £25,000?", "Not yet. PUR.DIR_LIMIT is 50000; IT changes it to 25000 on the evening of 30 November 2026 (AMD-PUR-2026-03, change log NBC-2026-026).", ["F-ADM-DIRLIMIT", "F-AMD3-1.2"], ["50000", "25000"], {}),
    ("Q-620", "version_conflict", "medium", "Was PUR.CERT_CHK switched on after the P4 patch?", "No. 7.2.3-P4 was installed on 20 September 2026 with PUR.CERT_CHK left at N, and the CAB (CR-2026-031) decided on 7 October not to enable it before January 2027.", ["F-LOG-P4", "F-LOG-CAB", "F-CAB-031"], ["CR-2026-031"], {}),
    # --------------------------------------------------------------------- exact code
    ("Q-701", "exact_code", "easy", "What is W-CC-114?", "A warning: the cost centre is closed and the document was saved as Draft (DR); the status bar only says SAVED. Amend the order to an open cost centre.", ["F-MAN-17.6", "F-RN723-WCC"], ["Draft"], {}),
    ("Q-702", "exact_code", "easy", "What does ERR-SCR-0221 mean?", "FETCH NOT DONE: the order was saved without Fetch for the current supplier and item. Press F3, check the values and save again.", ["F-MAN-17.3", "F-MAN-11.3"], ["F3"], {}),
    ("Q-703", "exact_code", "easy", "What does ERR-PO-0610 mean?", "Direct PO limit exceeded, raise PR: a DIR order's gross value is above the direct-order limit. Raise a purchase request, get it approved, then a STD order.", ["F-MAN-17.4"], ["raise a purchase request"], {}),
    ("Q-704", "exact_code", "easy", "What does ERR-SUP-0031 mean?", "Supplier not active: the supplier is BLOCKED. Use its active code (e.g. VC-EIN-0042 instead of VC-EIN-0009).", ["F-MAN-17.17", "F-SUP-5.2"], ["BLOCKED"], {}),
    ("Q-705", "exact_code", "easy", "What does ERR-SUP-0118 mean?", "VAT number already registered: search for the supplier and use the existing code; do not create a second record.", ["F-MAN-17.18"], ["existing code"], {}),
