def extra_table_questions(c):
    """Programmatic table lookups on the extended master data (beyond the seed), planted now on the item master."""
    book = next(o for o in c.outputs if isinstance(o, Book) and o.path.endswith("ITEM_MASTER_2026-10-26.xlsx"))
    out = []
    picks = ["TYR-28-PCT-2.0", "RIM-27.5-AL-DW", "LGT-REB", "CTL-03", "MTR-MID-500", "BAT-625-INT", "FST-BLT-M6X20-SS", "SDL-02"]
    for i, code in enumerate(picks, 1):
        it = c.w.item[code]
        fid = f"F-ITM-X{i:02d}"
        book.fact(fid, f"Item master: {code} '{it['descr']}', reorder level {it['reorder_lvl']}, lithium-cell flag {it['cell_safety']}.", "Items", code, "reorder_lvl",
                  extra=[(code, "descr"), (code, "cell_safety")])
        out.append((f"Q-43{i}", "table_lookup", "easy", f"What is the reorder level of {code} and is it a lithium-cell part?",
                    f"{code} ({it['descr']}): reorder level {it['reorder_lvl']}; lithium-cell flag {it['cell_safety']} ({'yes' if it['cell_safety'] else 'no'}).",
                    [fid], [str(it["reorder_lvl"])], {}))
    return out


def extra_code_questions(c):
    """Exact-code questions on generated (non-purchasing) error codes, planted on the error-code reference."""
    d = next(o for o in c.outputs if o.path.endswith("MAN-ERR-72 Message and Error Code Reference v7.2.3.pdf"))
    out = []
    for i, code in enumerate(["ERR-BNK-0101", "ERR-PAY-0430", "ERR-WO-0310", "ERR-RMA-0211", "ERR-QIN-0230", "ERR-CRD-0207", "ERR-ECN-0220", "ERR-PER-0010"], 1):
        e = c.cat.errors[code]
        fid = f"F-ERR-X{i:02d}"
        d.fact(fid, f"MAN-ERR-72: {code} {e['msg']}.", [f"{code} {e['msg']}"], section=f"{code} {e['msg']}")
        out.append((f"Q-72{i}", "exact_code", "medium", f"What does {code} mean?", f"{code} {e['msg']}.", [fid], [e["msg"].split(" (")[0]], {}))
    return out


def extra_service_questions(c):
    out = []
    for i, name in enumerate(["itm_search", "sup_rate_get", "bud_check", "tax_compute", "po_hist", "ntf_send", "pr_approve", "po_reject"], 1):
        s = c.cat.by_name[name]
        req = [f["name"] for f in s["fields"] if f["required"]]
        out.append((f"Q-33{i}", "service_field", "medium", f"What are the required fields of {name}?",
                    f"{name} ({s['title']}): required {', '.join(req) or 'none'}" + (f"; optional {', '.join(f['name'] for f in s['fields'] if not f['required'])}" if any(not f['required'] for f in s['fields']) else "") + ".",
                    [f"F-SVC-{name}"], req[:2], {}))
    return out


def build(c):
    qs = list(Q) + extra_table_questions(c) + extra_code_questions(c) + extra_service_questions(c)
    return qs
